INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'IN_ORDER_TO_INCREASE','Budući da nam je cilj razviti mrežu distributera i proširiti geografski doseg za distribuciju opreme za ugostiteljstvo, upućujemo poziv tvrtkama koje su zainteresirane da postanu ovlašteni trgovci za dugoročnu suradnju. Naše partnerstvo s distributerima nudi atraktivne pogodnosti, uključujući slojevitu strukturu popusta, fleksibilne mogućnosti isporuke i plaćanja, sveobuhvatan paket transportnih i logističkih usluga, pristup tehničkim resursima i marketinški kolateral. Štoviše, trgovci koji aktivno sudjeluju u nabavi na državnim natječajima kvalificirani su za bonus programe poticaja koji pružaju poboljšane razine popusta.');
