INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'IS_NOT_ACTIVE_DEALER_TEXT','Druga ugovorna strana trenutno je deaktivirana u našem računovodstvenom sustavu.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'IS_NOT_ACTIVE_DEALER_HELP','Vaš račun druge ugovorne strane je deaktiviran. Za dodatne pojedinosti obratite se svom upravitelju.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'IS_NOT_SALES_TYPES_TEXT','U našem računovodstvenom sustavu nije naveden smjer prodaje.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'IS_NOT_SALES_TYPES_HELP','Smjer prodaje za vaš račun nije naveden u našem računovodstvenom sustavu. Obratite se svom upravitelju kako biste svojoj drugoj strani dodijelili smjer prodaje.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'DEALERS_API_DOC','API dokumentacija trgovaca');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'API_SUPERVISOR_ROLE_REQUIRED','Za generiranje API ključa morate imati račun s ulogom "Nadzornik". Ako vaša tvrtka trenutno nema takav račun, obratite se svom upravitelju. Alternativno, ako samo trebate izraditi API ključ za buduću upotrebu, a vaša tvrtka već ima račun "Nadzornika", obratite se vlasniku računa.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'API_API_KEY_WARNING','Generiranjem i korištenjem API ključa potvrđujete da se slažete s uvjetima korištenja. Svi zahtjevi napravljeni pomoću vašeg API ključa bit će pripisani vama. Imajte na umu da će generiranje novog API ključa deaktivirati sve prethodno stvorene ključeve. Bit će potrebno ažurirati ključ u svim sustavima koji ga koriste.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'IS_NOT_ENTITY_FOR_PRICES','Naš računovodstveni sustav nema registriranu pravnu osobu. Za pristup cjenicima potrebna je aktivna pravna osoba. Obratite se svom upravitelju kako biste riješili ovaj problem.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'LINKS_TO_PRICE_BACKWARD','Linkovi na cjenike s kompatibilnošću unazad');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'ATTENTION_DIRECT_LINKS','"Obavijest! Izravne veze za preuzimanje sadrže vaš API ključ u nekriptiranom obliku. Nemojte dijeliti ove veze javno ili s bilo kim osim s tehničkim stručnjacima koji su uključeni u integraciju kataloga. Dijeljenje vašeg ključa daje pristup obradi transakcija i isporuka u ime vaše pravne osobe. "');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'IF_FOR_SOME_REASON_NEW_LINKS','Ukoliko novi linkovi za preuzimanje cjenika iz bilo kojeg razloga nisu prikladni, možete koristiti linkove navedene u tablici ispod. Format i sadržaj ovih starih cjenika u potpunosti su u skladu s vama poznatim. Međutim, imajte na umu da stari cjenici ne nude mogućnost odabira robe na temelju raspoloživosti, isključivanja PDV-a iz cijene robe ili uzimanja u obzir personaliziranih uvjeta ugovora vaše pravne osobe. Ako želite koristiti ove nove funkcije, pogledajte opcije u nastavku.');
