INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICE_FULL_RETAIL_CSV_TEXT','<p>Sadrži <b>maksimalni</b> podatak o proizvodu koji je dostupan u prilagođenoj vrsti opisa (dobavljač.model). Vrsta cijene - <b>preporučena maloprodaja</b>.</p>');
