INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICE_TO_GET_DIRECT_LINK','Morate imati račun s ulogom "Nadzornik" kako biste dobili izravne veze za preuzimanje cjenika. Ako nemate račun s ovom ulogom, obratite se svom upravitelju. Ako trebate samo izravne poveznice za njegovo daljnje korištenje, a vaša tvrtka ima “Supervisor” račun, obratite se njegovom vlasniku.');
