INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_AVAIL','Dostupnost: u skladištu. Uzima vrijednosti <b>true</b> ako je proizvod dostupan u navedenom skladištu, inače <b>false</b>.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_DESC',' Opis proizvodaponuda.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_PURCHASE_TYPE','Vrsta kupnje. Može uzeti vrijednosti:<br/> <ul> <li><b>"in stock"</b> - artikl je na skladištu barem u jednom od odabranih skladišta</li> <li><b>"na putu"</b> - artikal je u najbližoj isporuci do skladišta u Moskvi</li> <li><b>"na zahtjev"</b> - roba se može donijeti u skladište u Moskvi na zahtjev. <b>Posebni uvjeti plaćanja</b> - provjerite kod upravitelja.</li> </ul>');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_DELIVERY_TIME','Vrijeme isporuke artikala na zahtjev do skladišta u Moskvi mjeri se u danima i može varirati unutar određenih vrijednosti:<br> <ul> <li><b>broj (dana)</b></li> <li> <b>"nije više dostupno"</b> - isporuke su zaustavljene,</li> <li><b>"provjeri"</b> - provjerite kod upravitelja,</li> <li>prazan redak - ako rok isporuke nije definiran</li> </ul>');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_VENDOR','Proizvođač ili marka (zaštitni znak).');
