INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_MODEL','Model i važni parametri (na primjer, indeks modela, značajke modifikacije itd.). Uzima vrijednost <b>undefined</b> ako nije postavljena.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_SALES_NOTES','Element služi za prikaz informacija o:<br> <ul> <li>potrebi dogovora o vremenu isporuke s upraviteljem;</li> <li>prekidu kupnje artikla (ne isporučujemo stavka više).</li> </ul>');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_DELIVERY_OPTIONS','Vrijeme isporuke <b>za artikle na zahtjev</b> do skladišta u Moskvi. Vrijednost se šalje u atributu <b>days</b>. Prikazuje se samo ako je za artikl dostupna dostava.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_WEIGHT','Element je dizajniran za određivanje težine artikla. <b>Težina je u kilogramima uključujući pakiranje</b>.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_DIMENSIONS','Element je dizajniran za određivanje dimenzija artikla (duljina, širina, visina) u pakiranju. <b>Dimenzije su u centimetrima</b>.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_DELIVERY','Dostupnost dostave. Prihvaća vrijednosti:<br> <ul> <li><b>false</b> — artikl više ne šaljemo ili trebate provjeriti vrijeme isporuke kod upravitelja;</li> <li><b >true</b> — artikl se može isporučiti;</li> </ul>');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'PRICES_D_PICKUP','Dostupnost za preuzimanje. Prihvaća vrijednosti:<br> <ul> <li><b>false</b> — artikal više ne isporučujemo i nema ga na skladištu;</li> <li><b>true</b > — artikal je na zalihi ili je dostava moguća na upit, odabrani artikl možete rezervirati i sami preuzeti;</li> </ul>');
