INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'GROUP_BRANDMANAGER_TEXT','Imate pristup odjeljku upita za svoju marku. Posebno za privatne robne marke, možete upravljati katalogom svoje robne marke na imex.gkrp.local, potvrditi prava preuzimanja datoteka i obavijestiti glavnog upravitelja o potvrdi korisničkog portala na vašoj stranici. Također možete pogledati cijene za sve cjenike, uključujući i one za EU.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'GROUP_ZIPMANAGER_TEXT','Imate pristup pregledu transakcija i povezanih informacija vezanih uz prodaju rezervnih dijelova, uključujući sve reklamacije, kao i pristup pregledu svih cjenika.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'GROUP_QUALITYMANAGER_TEXT','Imate pristup svim upitima o transakcijama, potraživanjima i pritužbama.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'GROUP_SENIORZIPMANAGER_TEXT','U mogućnosti ste pregledavati transakcije i povezane informacije vezane uz prodaju rezervnih dijelova, rješavati sve reklamacije, pristupiti svim cjenicima, upravljati zaposlenicima unutar vašeg odjela, slati obavijesti voditelju o korisničkim potvrdama na portalu (ako je korisnik vaš kupac), te registrirati transakcije u ime protuusluge u smjeru prodaje rezervnih dijelova.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'GROUP_SENIORQUALITYMANAGER_TEXT','Imate pristup svim transakcijama, reklamacijama i upitima (dopunama) vezanim uz reklamacije. Također, možete uređivati zaposlenike unutar svog odjela.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'GROUP_SENIORCOMPLAINTMANAGER_TEXT','Imate pristup svim transakcijama, reklamacijama i upitima (dopunama) vezanim uz reklamacije. Također, možete uređivati zaposlenike unutar svog odjela.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'GROUP_COMPLAINTMANAGER_TEXT','Imate pristup zahtjevima za koje ste dodijeljeni kao glavni inženjer.');
