INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_NAME','Unesite naziv proizvoda za prikaz u katalogu. Imajte na umu da ako proizvod već postoji u katalogu, naziv se možda neće pojaviti. Promjena ovog polja zahtijevat će ponovno moderiranje proizvoda.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_BRAND','Unesite marku proizvoda. Ako proizvod već postoji u katalogu, robne marke proizvoda moraju odgovarati. Promjena ovog polja zahtijevat će ponovno moderiranje proizvoda.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_CATEGORY','Odaberite kategoriju proizvoda za prikaz u katalogu. Ako proizvod već postoji u katalogu, kategorije proizvoda moraju odgovarati. Promjena ovog polja zahtijevat će ponovno moderiranje proizvoda.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_CODE_1C','Popunjava se samo ako takav proizvod već postoji u katalogu. Ako nije, polje mora ostati prazno.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_PRICE','Unesite cijenu proizvoda bez navođenja valute.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_CURRENCY','Odaberite valutu u kojoj je naznačena cijena proizvoda.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_QUANTITY_IN_PACKAGE','Ukoliko se proizvod prodaje u pakiranju ili kompletu, molimo upišite količinu proizvoda u jednom pakiranju. Ako ovo polje ostane prazno, automatski će se smatrati 1 artiklom po paketu.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_FBS','Unesite količinu proizvoda koju želite prodati putem FBS sustava. Ostavite ovo polje prazno ako ne želite prodavati proizvode putem FBS sustava.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_DELIVERY_TIME','Unesite broj dana koji će biti potreban da roba iz narudžbe stigne u vaše skladište. To će uključiti vrijeme isporuke od vašeg skladišta do skladišta Equip pri izračunu isporuke kupcu. Ostavite ovo polje prazno ako ne želite prodavati proizvode po narudžbi.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_DESCRIPTION','Unesite opis proizvoda. Imajte na umu da ako proizvod već postoji u katalogu, opis možda neće biti prikazan na kartici proizvoda. Promjena ovog polja zahtijevat će ponovno moderiranje proizvoda.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_LENGTH','Unesite duljinu proizvoda bez pakiranja u milimetrima. Promjena ovog polja zahtijevat će ponovno moderiranje proizvoda.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_HEIGHT','Unesite visinu proizvoda bez pakiranja u milimetrima. Promjena ovog polja zahtijevat će ponovno moderiranje proizvoda.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_WIDTH','Unesite širinu proizvoda bez pakiranja u milimetrima. Promjena ovog polja zahtijevat će ponovno moderiranje proizvoda.');
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,6,'TOOLTIP_GROSSLENGTH','Unesite duljinu proizvoda u paketu u milimetrima. Promjena ovog polja zahtijevat će ponovno moderiranje proizvoda.');
